script:
# After Submit on Stock Entry.
# For multi-drop / stage-4 receipt SEs that use the custom parent-level
# link `material_request_new`, roll up per-item received qty across all
# submitted receipt SEs for that MR and update MR status.

if doc.purpose != "Material Transfer":
    pass
elif not doc.get("outgoing_stock_entry"):
    pass
elif not doc.get("material_request_new"):
    pass
else:
    mr_name = doc.get("material_request_new")
    try:
        mr = frappe.get_doc("Material Request", mr_name)
    except Exception as e:
        frappe.log_error(
            title="Sungas MR Auto Status — MR fetch failed",
            message=("MR: " + str(mr_name) + "\n" + str(e)),
        )
        mr = None

    if mr is None:
        pass
    elif mr.status == "Transferred":
        pass
    elif mr.docstatus != 1:
        pass
    else:
        # Sum received qty per item across every submitted receipt SE for this MR.
        received_by_item = {}
        se_rows = frappe.get_all(
            "Stock Entry",
            filters={
                "material_request_new": mr_name,
                "docstatus": 1,
                "purpose": "Material Transfer",
            },
            fields=["name"],
        ) or []
        se_names = []
        for r in se_rows:
            if r.get("outgoing_stock_entry") is None:
                # get_all above doesn't return outgoing_stock_entry — refetch minimally
                pass
            se_names.append(r.get("name"))

        # Refine: only receipt legs (outgoing_stock_entry set)
        receipt_names = []
        for n in se_names:
            og = frappe.db.get_value("Stock Entry", n, "outgoing_stock_entry")
            if og:
                receipt_names.append(n)

        for n in receipt_names:
            se_items = frappe.get_all(
                "Stock Entry Detail",
                filters={"parent": n, "parenttype": "Stock Entry"},
                fields=["item_code", "qty"],
            ) or []
            for si in se_items:
                code = si.get("item_code")
                received_by_item[code] = received_by_item.get(code, 0) + (si.get("qty") or 0)

        # Update MR items: ordered_qty and received_qty tracked per item.
        total_qty = 0
        total_received = 0
        # Refresh a live MR to write on
        for it in (mr.items or []):
            requested = it.qty or 0
            received = received_by_item.get(it.item_code, 0)
            total_qty = total_qty + requested
            total_received = total_received + min(received, requested)
            # Fully-linked qty across siblings — proportional split when MR has 1 item is trivial
            frappe.db.set_value(
                "Material Request Item", it.name,
                {"ordered_qty": min(received, requested),
                 "received_qty": min(received, requested)},
                update_modified=False,
            )

        if total_qty > 0:
            pct = round((total_received / total_qty) * 100, 2)
        else:
            pct = 0

        new_status = mr.status
        if pct >= 100:
            new_status = "Transferred"
        elif pct > 0:
            new_status = "Partially Received"

        frappe.db.set_value(
            "Material Request", mr_name,
            {"per_ordered": pct, "per_received": pct, "status": new_status},
            update_modified=False,
        )

# Skip PR-discharge SEs — they have their own Stage-2 flow
if doc.get("is_pr_discharge") or doc.get("pr_reference") or doc.get("pr_reference_new"):
    pass

else:
    is_dispatch_leg = bool(doc.get("final_destination_warehouse") or doc.get("material_request_new") or doc.get("is_multi_drop"))
    is_receipt_leg = bool(doc.get("outgoing_stock_entry"))

    if not (is_dispatch_leg or is_receipt_leg):
        # Not an inter-outlet SE (Repack, Material Issue, intra-bin transfer) — pass
        pass

    else:
        submitter = frappe.session.user
        role_rows = frappe.get_all(
            "Has Role", filters={"parent": submitter}, fields=["role"]
        ) or []
        roles = {r.get("role") for r in role_rows}
        has_hoo = "LPG Head of Operations" in roles
        has_coo = "COO" in roles
        has_pm = "LPG Plant Manager" in roles

        # ── Dispatch leg ─────────────────────────────────────────────────
        if is_dispatch_leg and not is_receipt_leg:
            # Rule (a): HoO or COO — break-glass / routine authority
            if has_hoo or has_coo:
                pass
            elif doc.get("is_multi_drop"):
                # Rule (b') MULTI-DROP: every destination_allocations row
                # must link to a Material Request AND every one of those
                # MRs must be hoo_approved=1.
                allocs = doc.get("destination_allocations") or []
                if not allocs:
                    frappe.throw(
                        "Multi-drop dispatch has no destination allocations. "
                        f"Submitter: {submitter}."
                    )
                unapproved = []
                missing = 0
                for row in allocs:
                    mr = row.get("material_request")
                    if not mr:
                        missing += 1
                        continue
                    if not frappe.db.get_value("Material Request", mr, "hoo_approved"):
                        unapproved.append(mr)
                if missing or unapproved:
                    parts = []
                    if missing:
                        parts.append(f"{missing} drop row(s) missing Material Request link")
                    if unapproved:
                        parts.append("MRs not HoO-approved: " + ", ".join(sorted(set(unapproved))))
                    frappe.throw(
                        "Multi-drop dispatch not authorised. " + "; ".join(parts) + ". "
                        f"Submitter: {submitter}. Either fix the MR linkage / approvals, "
                        "or have LPG Head of Operations / COO submit."
                    )
            else:
                # Rule (b) SINGLE-DROP: linked material_request_new must be hoo_approved
                mr_name = doc.get("material_request_new")
                mr_approved = False
                if mr_name:
                    mr_approved = bool(frappe.db.get_value("Material Request", mr_name, "hoo_approved"))
                if not mr_approved:
                    frappe.throw(
                        "Inter-outlet dispatch not authorised. "
                        "Either the linked Material Request must be hoo_approved=1, "
                        "or the submitter must hold LPG Head of Operations / COO. "
                        f"Submitter: {submitter}. "
                        f"Linked MR: {mr_name or '(none)'}."
                    )

        # ── Receipt leg ─────────────────────────────────────────────────
        elif is_receipt_leg:
            # Anyone with PM / HoO / COO can submit a receipt for an approved dispatch.
            if not (has_pm or has_hoo or has_coo):
                frappe.throw(
                    "Inter-outlet receipt submit requires LPG Plant Manager, "
                    "LPG Head of Operations, or COO role. "
                    f"Submitter: {submitter}."
                )

            # Resolve the MR for this receipt: prefer the receipt SE's own
            # material_request_new (multi-drop spawn writes it per drop);
            # fall back to the parent dispatch's material_request_new
            # (single-drop legacy flow).
            parent_dispatch = doc.get("outgoing_stock_entry")
            mr_for_check = doc.get("material_request_new")
            if not mr_for_check and parent_dispatch:
                mr_for_check = frappe.db.get_value(
                    "Stock Entry", parent_dispatch, "material_request_new"
                )
            if mr_for_check:
                approved = bool(frappe.db.get_value(
                    "Material Request", mr_for_check, "hoo_approved"
                ))
                if not approved and not (has_hoo or has_coo):
                    frappe.throw(
                        f"Cannot submit receipt: Material Request "
                        f"{mr_for_check} is not HoO-approved. "
                        "Escalate to HoO or COO."
                    )

# Sungas · DLS before_save — enforce drop-row integrity from the linked MR.
# Prevents ops from manipulating destination/qty/item on a drop after selection.

seen_mrs = set()
for drop in (doc.drops or []):
    if not drop.material_request:
        frappe.throw("Every drop row requires a Material Request.")
    if drop.material_request in seen_mrs:
        frappe.throw("MR " + drop.material_request + " is listed twice. Remove the duplicate row.")
    seen_mrs.add(drop.material_request)

    mr = frappe.get_doc("Material Request", drop.material_request)
    if mr.material_request_type != "Material Transfer":
        frappe.throw("MR " + drop.material_request + " is not a Material Transfer.")
    if not mr.hoo_approved:
        frappe.throw("MR " + drop.material_request + " is not HoO-approved.")
    if mr.docstatus != 1:
        frappe.throw("MR " + drop.material_request + " must be Submitted (not just Saved) before it can be dispatched. Open the MR and click Submit.")
    if doc.source_outlet and mr.source_outlet and mr.source_outlet != doc.source_outlet:
        frappe.throw("MR " + drop.material_request + " is sourced from " + mr.source_outlet
                     + " but this Loading Schedule loads at " + doc.source_outlet
                     + ". One DLS per source outlet.")
    drop.destination_outlet = mr.set_warehouse
    if mr.items:
        first = mr.items[0]
        drop.item_code = first.item_code
        if not drop.qty or drop.qty <= 0 or drop.qty > first.qty:
            drop.qty = first.qty
        drop.uom = first.uom or "Kg"

# Before Submit on Stock Entry.
# Block Material Receipt SEs that reference a Material Transfer MR — those
# must go through the 3-leg pattern: outward (source → GIT) + receipt
# (GIT → destination). A Material Receipt would inflate the destination
# without decrementing the source, creating phantom stock.

if doc.stock_entry_type != "Material Receipt":
    pass  # only Material Receipt is at risk

else:
    # Privilege bypass — HoO / CoO / SysMgr can force through if the
    # accounting truth actually is a receipt (e.g. donated stock they
    # are formally accepting).
    user = frappe.session.user
    priv_roles = ["System Manager", "LPG Head of Operations",
                  "LPG Chief Operating Officer", "LPG Head of Finance"]
    user_roles = frappe.get_all(
        "Has Role", filters={"parent": user}, pluck="role"
    ) or []
    is_privileged = False
    for r in priv_roles:
        if r in user_roles:
            is_privileged = True
    if is_privileged:
        pass  # skip guard for privileged operators
    else:
        # Gather all MR references from this SE
        mrs = set()
        if doc.get("material_request_new"):
            mrs.add(doc.material_request_new)
        for it in (doc.items or []):
            if it.get("material_request"):
                mrs.add(it.material_request)

        offending = None
        for mr_name in mrs:
            mr_type = frappe.db.get_value(
                "Material Request", mr_name, "material_request_type"
            )
            if mr_type == "Material Transfer":
                offending = mr_name
                break

        if offending:
            frappe.throw(
                "Cannot submit a Material Receipt against Material Request "
                + offending + " because it is a Material Transfer. "
                "Inter-outlet transfers must move through Goods In Transit "
                "so the source outlet's stock is decremented. Change the "
                "Stock Entry Type to \"Material Transfer\" with "
                "from_warehouse = Goods In Transit - SCL, or ask HoO to "
                "override if this is genuinely a receipt without a source."
            )

# After Save on Daily Loading Schedule.
# When state transitions to "Dispatched", spawn one multi-drop outward
# Stock Entry (<source> → GIT) from the DLS drops. Idempotent via
# doc.dispatch_stock_entry link field.

TRANSIT_WH = "Goods In Transit - SCL"

if doc.state != "Dispatched":
    pass  # only fire on Dispatched

elif doc.get("dispatch_stock_entry"):
    pass  # already spawned — no-op

elif not doc.source_outlet:
    pass  # cannot spawn without a source

elif not (doc.drops or []):
    pass  # nothing to dispatch

else:
    # Guard: every drop must reference a Submitted + hoo_approved MR.
    ok = True
    for drop in (doc.drops or []):
        if not drop.material_request:
            ok = False
            break
        mr_row = frappe.db.get_value(
            "Material Request",
            drop.material_request,
            ["hoo_approved", "docstatus"],
            as_dict=True,
        ) or {}
        if not mr_row.get("hoo_approved") or int(mr_row.get("docstatus") or 0) != 1:
            frappe.throw(
                "MR " + drop.material_request + " must be Submitted and "
                "HoO-approved before dispatch. Fix that row first."
            )
    if not ok:
        pass  # guard rejected — msgs already surfaced
    else:
        # Resolve source warehouse dimensions (cost_center / region / branch)
        wh_defs = frappe.db.get_value(
            "Warehouse",
            doc.source_outlet,
            ["custom_default_cost_center", "custom_sungas_region",
             "custom_sungas_branch"],
            as_dict=True,
        ) or {}

        # Resolve Company defaults (stock adjustment account)
        company = doc.company or frappe.db.get_single_value("Global Defaults", "default_company")
        company_stock_adj = frappe.db.get_value(
            "Company", company, "stock_adjustment_account"
        ) if company else None

        # Aggregate qty per item across all drops.
        by_item = {}
        allocations = []
        for drop in (doc.drops or []):
            key = drop.item_code
            if not key:
                continue
            by_item[key] = by_item.get(key, 0) + (drop.qty or 0)
            allocations.append({
                "destination_outlet": drop.destination_outlet,
                "item_code": drop.item_code,
                "allocated_qty": drop.qty or 0,
                "weighbridge_qty": drop.qty or 0,
                "material_request": drop.material_request,
            })

        if not by_item:
            pass  # every drop was invalid — bail
        else:
            se = frappe.new_doc("Stock Entry")
            se.stock_entry_type = "Material Transfer"
            se.company = company
            se.purpose = "Material Transfer"
            se.from_warehouse = doc.source_outlet
            se.to_warehouse = TRANSIT_WH
            se.loading_schedule = doc.name
            se.is_multi_drop = 1
            se.posting_date = frappe.utils.today()
            se.set_posting_time = 0
            if doc.get("truck_no"):
                se.pr_truck_registration = doc.truck_no

            for it_code, tot_qty in by_item.items():
                item_row = {
                    "item_code": it_code,
                    "qty": tot_qty,
                    "uom": "Kg",
                    "stock_uom": "Kg",
                    "conversion_factor": 1,
                    "s_warehouse": doc.source_outlet,
                    "t_warehouse": TRANSIT_WH,
                }
                if wh_defs.get("custom_default_cost_center"):
                    item_row["cost_center"] = wh_defs["custom_default_cost_center"]
                if wh_defs.get("custom_sungas_region"):
                    item_row["sungas_region"] = wh_defs["custom_sungas_region"]
                if wh_defs.get("custom_sungas_branch"):
                    item_row["branch"] = wh_defs["custom_sungas_branch"]
                if company_stock_adj:
                    item_row["expense_account"] = company_stock_adj
                se.append("items", item_row)

            for alloc in allocations:
                se.append("destination_allocations", alloc)

            try:
                se.insert(ignore_permissions=True)
                # Back-link on the DLS (idempotent stamp)
                doc.dispatch_stock_entry = se.name
                doc.db_set("dispatch_stock_entry", se.name, update_modified=False)
                frappe.msgprint(
                    "Draft outward Stock Entry " + se.name + " created — "
                    "review + Submit to release stock from " + doc.source_outlet + ".",
                    alert=True, indicator="green",
                )
            except Exception as e:
                frappe.log_error(
                    "DLS Dispatch → Outward SE Spawn failed for " + doc.name
                    + ": " + str(e),
                    "Sungas DLS Auto-Spawn",
                )

# Sungas · Stock Entry before_save — enforce Difference Account (Stock Adj)
# and outlet dimensions (cost centre / region / branch) on each item row.
#
# The field labelled "Difference Account" in the UI is stored as
# item.expense_account on Stock Entry Detail. For Material Transfer,
# valuation drift must never hit COGS — always route to Stock Adjustment.
#
# Cost-centre / region / branch come from the item's OUTLET warehouse
# (not the shared GIT transit warehouse). We try t_warehouse then
# s_warehouse and pick the first one that carries the Sungas custom
# defaults.

company_stock_adj = None
company_default_expense = None
if doc.company:
    company_stock_adj = frappe.db.get_value("Company", doc.company, "stock_adjustment_account")
    company_default_expense = frappe.db.get_value("Company", doc.company, "default_expense_account")

is_transfer = doc.stock_entry_type == "Material Transfer"

def resolve_outlet_defaults(candidates):
    for wh in candidates:
        if not wh:
            continue
        rows = frappe.get_all(
            "Warehouse",
            filters={"name": wh},
            fields=["custom_default_cost_center", "custom_sungas_region", "custom_sungas_branch"],
            limit=1
        ) or []
        if not rows:
            continue
        r = rows[0]
        if r.get("custom_default_cost_center") or r.get("custom_sungas_region") or r.get("custom_sungas_branch"):
            return r
    return None

for item in (doc.items or []):
    # Difference Account — force Stock Adjustment on Material Transfer;
    # otherwise only fill if empty so we don't disturb Manufacture/Repack.
    if company_stock_adj:
        current = item.expense_account
        if is_transfer and (not current or current == company_default_expense):
            item.expense_account = company_stock_adj
        elif not current:
            item.expense_account = company_stock_adj

    if not is_transfer:
        continue

    # Outlet-scoped dimension overrides — pick the first warehouse
    # (destination-preferred) that has Sungas defaults.
    defs = resolve_outlet_defaults([
        item.t_warehouse,
        item.s_warehouse,
        doc.to_warehouse,
        doc.from_warehouse,
    ])
    if not defs:
        continue
    if defs.get("custom_default_cost_center"):
        item.cost_center = defs["custom_default_cost_center"]
    if defs.get("custom_sungas_region"):
        item.sungas_region = defs["custom_sungas_region"]
    if defs.get("custom_sungas_branch"):
        item.branch = defs["custom_sungas_branch"]

# Sungas · DLS row-level scope.
# Plant Managers only see DLS for source outlets they own.
# Managers see everything.

user = frappe.session.user
if user == "Administrator" or user == "lmd-bot@sungas.org" or user == "Guest":
    conditions = ""
else:
    roles = frappe.get_all("Has Role", filters={"parent": user}, pluck="role") or []
    priv = ["System Manager", "LPG Head of Operations",
            "LPG Head of Finance", "Stock Manager",
            "Accounts Manager", "Purchase Manager"]
    is_privileged = False
    for r in priv:
        if r in roles:
            is_privileged = True
    if is_privileged:
        conditions = ""
    else:
        wh_rows = frappe.get_all(
            "Warehouse",
            filters={"outlet_plant_manager": user, "disabled": 0},
            pluck="name"
        ) or []
        wh_names = []
        for n in wh_rows:
            wh_names.append("'" + n.replace("'", "''") + "'")
        user_esc = user.replace("'", "''")
        if wh_names:
            wh_list = ",".join(wh_names)
            conditions = (
                "(`tabDaily Loading Schedule`.owner='" + user_esc + "' "
                "OR `tabDaily Loading Schedule`.source_outlet IN (" + wh_list + "))"
            )
        else:
            conditions = "`tabDaily Loading Schedule`.owner='" + user_esc + "'"

# Sungas · Material Request — set item accounting dimensions from destination Warehouse.
# Fires before_save so it wins over Frappe's Item Default fetch.

def wh_defaults(warehouse):
    if not warehouse:
        return None
    rows = frappe.get_all(
        "Warehouse",
        filters={"name": warehouse},
        fields=["custom_default_cost_center", "custom_sungas_region", "custom_sungas_branch"],
        limit=1
    ) or []
    return rows[0] if rows else None

for item in (doc.items or []):
    wh = item.warehouse or doc.set_warehouse
    defs = wh_defaults(wh)
    if not defs:
        continue
    if defs.get("custom_default_cost_center"):
        item.cost_center = defs["custom_default_cost_center"]
    if defs.get("custom_sungas_region"):
        item.sungas_region = defs["custom_sungas_region"]
    if defs.get("custom_sungas_branch"):
        item.branch = defs["custom_sungas_branch"]

if not doc.is_new():
    SENIORS = {'System Manager', 'Sales Manager', 'Accounts Manager', 'LPG Plant Manager', 'LPG Head of Sales', 'LPG Head of Finance'}
    user_roles = {r.role for r in frappe.db.get_all('Has Role', filters={'parent': frappe.session.user, 'parenttype': 'User'}, fields=['role'])}
    if 'LPG POS User' in user_roles and not (user_roles & SENIORS):
        frappe.throw('Cashiers cannot edit existing customer profiles.')

# safe_exec does not expose frappe.get_roles; read Has Role child table instead.
SENIORS = {'System Manager', 'Sales Manager', 'Accounts Manager', 'LPG Plant Manager', 'LPG Head of Sales', 'LPG Head of Finance'}
user_roles = {r.role for r in frappe.db.get_all('Has Role', filters={'parent': frappe.session.user, 'parenttype': 'User'}, fields=['role'])}
if 'LPG POS User' in user_roles and not (user_roles & SENIORS):
    doc.customer_group = 'Retail'
